45	  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') { W.panBy(0, e.key === 'ArrowUp' ? 60 : -60); e.preventDefault(); }
46	  if (e.key === '+' || e.key === '=') W.zoomBy(1.25); if (e.key === '-') W.zoomBy(0.8);
47	  if (e.key === 'q' || e.key === '[') camCmd('rotL'); if (e.key === 'e' || e.key === ']') camCmd('rotR');
