76	  setTab, beginRun, stopRun, nextSeason, buy, changed, refreshWorld, pickRoom, camCmd, tapAt, hoverAt, rotateArmed, rotateSelected,
77	  fastForward, skipNumber, view: W.view, camera: W.camera, renderer: W.renderer, project: W.project, tileCentre: W.tileCentre, snapCam: W.snapCam,
78	  get frames() { return G.frames; },
79	  get run() { const r = G.run; return r && { mode: r.mode, t: r.t, done: r.done, feed: r.feed.map((f) => f.text), points: r.res.points }; },
