  if (e.key === '+' || e.key === '=') W.zoomBy(1.25); if (e.key === '-') W.zoomBy(0.8);
  if (e.key === 'q' || e.key === '[') camCmd('rotL'); if (e.key === 'e' || e.key === ']') camCmd('rotR');
  if (e.key === 'r' || e.key === 'R') { if (G.armed) rotateArmed(); else if (G.selected) rotateSelected(); }
  if (e.key === 'Escape') { if (G.armed) { G.armed = null; W.setGhost(null); paintSheet(); } else if (G.pickedRoom && G.tab !== 'build') pickRoom(null); }
});

/* ---------------- the loop ---------------- */
let last = performance.now(), hudK = -1, paintK = -1;
function frame(now) {
  requestAnimationFrame(frame); G.frames++;
  const dt = Math.min(0.05, (now - last) / 1000); last = now; G.realT += dt;
  stepRun(dt); tickMusic();
  if (G.run) {
    stepScene(dt);
    if (Math.floor(G.realT * 2) !== hudK) { hudK = Math.floor(G.realT * 2); hud(); }
    if (G.screen === 'run' && !G.run.done && Math.floor(G.realT * 4) !== paintK) { paintK = Math.floor(G.realT * 4); paintRunSheet(); }
  } else W.stepLights(dt, false, false);
  W.curtain.open += (W.curtain.target - W.curtain.open) * Math.min(1, dt * 3);
  W.curtain.halves.forEach((g) => { g.scale.x = 1 - W.curtain.open * 0.86; });
  updateDancers(dt); W.spinFans(dt);
  W.placeCamera(dt); placeFloat();
  W.renderer.render(W.scene, W.camera);
}
addEventListener('resize', resize);
if (window.ResizeObserver) { const ro = new ResizeObserver(() => resize()); ro.observe(document.getElementById('sheet')); ro.observe(document.getElementById('cam')); }
requestAnimationFrame(frame);

/* ---------------- the drive's handle ---------------- */
window.__game = {
  G, get S() { return G.S; }, simulate, stageOf, routineInfo, analyseLoge, CLS, NUMBERS, RULES, danceAt,
  setTab, beginRun, stopRun, nextSeason, buy, changed, refreshWorld, pickRoom, camCmd, tapAt, hoverAt, rotateArmed, rotateSelected,
  fastForward, skipNumber, view: W.view, camera: W.camera, renderer: W.renderer, project: W.project, tileCentre: W.tileCentre, snapCam: W.snapCam,
  get frames() { return G.frames; },
  get run() { const r = G.run; return r && { mode: r.mode, t: r.t, done: r.done, feed: r.feed.map((f) => f.text), points: r.res.points }; },
  dancers: () => dancers.map((d) => ({ id: d.id, x: +d.g.position.x.toFixed(2), y: +d.g.position.y.toFixed(2), z: +d.g.position.z.toFixed(2), visible: d.g.visible, emoji: d.emoji, wearing: d.wearing })),
  fitReport: () => { const spec = W.viewSpec(), u = W.usable(); const pts = spec.pts.map((q) => { const v = q.clone().project(W.camera); return { x: +v.x.toFixed(3), y: +v.y.toFixed(3) }; }); return { mode: W.view.mode, inside: pts.every((v) => v.x >= u.x0 - 0.03 && v.x <= u.x1 + 0.03 && v.y >= u.y0 - 0.03 && v.y <= u.y1 + 0.03), pts }; },
  snapDancers, idle, music: musicState, wake,
  furnitureDrawn: () => W.furnG.children.filter((o) => o.userData.f).length,
};

content.content:
1	// The side sheet: the preparations (one tab per problem), the live evening, the verdicts, the shop. Everything she sets is
2	// written into G.S.plan or G.S.school, saved, and the day is simulated again from scratch.
3	import { G, save, resetAll } from './state.js';
4	import {
5	  RULES, CLS, NUMBERS, numDur, itemKind, STYLES, MOVES, MAX_MOVES, LEVELS, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE, SNACKS, UPGRADES,
6	  BACKDROPS, PARKING, COLORS, seasonRules, hm,
7	} from './data.js';
8	import { simulate, routineInfo, danceOf, judgeMusic, stageOf, isOwned, fits, againstWall, footprint, analyseLoge, clamp, seatsOf } from './engine.js';
9	import { addSeasonNumbers } from './plan.js';
10	import { t, nm, clsName, numName, dancerName, moveName, itemName, styleName, clockOf, durOf, num } from './i18n.js';
11	import * as W from './world.js';
12	import { wake } from './music.js';
13	import { TUNES } from './tunes.js';
14	import { dancers, buildDancers, redressAll, idle, idleScene, startRun, stepRun, skipNumber, fastForward, snapDancers } from './play.js';
15	
16	const $ = (s) => document.querySelector(s);
17	const sheet = $('#sheet'), sbody = $('#sbody'), tabsEl = $('#tabs'), goEl = $('#go'), toastEl = $('#toast'), camBar = $('#cam'), modal = $('#modal'), floatEl = $('#float');
18	export const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
19	let toastT; export function toast(text) { toastEl.textContent = text; toastEl.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('show'), 2600); }
20	const rules = () => seasonRules(G.S.season);
21	const activeNums = () => G.S.plan.order.filter((id) => NUMBERS[id] && rules().classes.includes(NUMBERS[id].cls));
22	const forecast = () => simulate({ plan: G.S.plan, school: G.S.school, season: G.S.season, mode: 'rehearsal', seed: G.S.seed });
23	const dot = (cls) => `<span class="dot" style="background:${cls ? CLS[cls].color : 'var(--accent)'}"></span>`;
24	const stepper = (id, label, value) => `<div class="step"><span class="lab">${esc(label)}</span><button type="button" data-st="${id}" data-d="-1" aria-label="−">−</button><output id="out-${id}">${esc(value)}</output><button type="button" data-st="${id}" data-d="1" aria-label="+">+</button></div>`;
25	const facts = (list) => `<ul class="facts">${list.map((f) => `<li>${f}</li>`).join('')}</ul>`;
26	const diffDots = (d) => '●'.repeat(d) + '○'.repeat(3 - d);
27	const LEVEL_ICON = ['⬇', '➖', '⬆'];
28	function bindSteppers(fn) { for (const b of sbody.querySelectorAll('[data-st]')) b.onclick = () => { fn(b.dataset.st, +b.dataset.d); changed(); }; }
29	// any change: save, re-simulate (the sheet reads the fresh day), put the dancers where the tab shows them
30	export function changed(opts = {}) { save(); if (!G.run) idle(); if (opts.world) refreshWorld(); paintSheet(); hud(); }
31	
32	/* ---------------- the world follows the save ---------------- */
33	export function refreshWorld() {
34	  const sc = G.S.school, up = sc.upgrades;
35	  W.buildLoge(); W.showFurniture(); W.buildSeats(up.sieges || 0, !!up.confort); W.showBuvette(up.buvette); W.buildLights(up);
36	  W.buildParking(G.S.plan.parking.width, up.rangee ? 2 : 1); W.showBackdrop(G.S.plan.backdrop); W.drawStageTape(stageOf(sc)); W.drawSign(schoolName()); W.setStageFloor('tapis');
37	  if (!G.run) idleScene();
38	}
39	export const schoolName = () => G.S.school.name || t().school;
40	
41	/* ---------------- buying ---------------- */
42	export function buy(kind, id, price, name) {
43	  const sc = G.S.school;
44	  if (sc.stars < price) { toast(t().notEnough); return false; }
45	  sc.stars -= price;
46	  if (kind === 'up') sc.upgrades[id] = id === 'sieges' ? (sc.upgrades[id] || 0) + 1 : true;
47	  else sc.owned[`${kind}:${id}`] = true;
48	  if (kind === 'up' && id === 'logeXL') sc.logeCols = LOGE.colsBig;
49	  toast(t().bought(name)); changed({ world: kind === 'up' });
50	  return true;
51	}
52	const priceOf = (kind, id) => (kind === 'up' ? UPGRADES[id].price : kind === 'food' ? 15 + (id === 'crepes' ? 5 : 0) : ({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS }[kind][id].price || 0));
53	
54	/* ---------------- the frame: top bar, camera bar, tabs ---------------- */
55	export function hud() {
56	  const run = G.run;
57	  $('#daychip').textContent = run && !run.done ? `${t().live(run.mode)} · ${clockOf(run.t, false)}` : '';
58	  $('#seasonchip').textContent = t().season(G.S.season);
59	  $('#starchip').textContent = t().stars(G.S.school.stars);
60	  $('#langBtn').textContent = t().lang;
61	  $('#brand').textContent = schoolName();
62	}
63	export function paintCamBar() {
64	  const v = t().views, m = W.view.mode;
65	  camBar.innerHTML = `<button type="button" data-c="rotL" title="${v.rotL}" aria-label="${v.rotL}">⟲</button><button type="button" data-c="rotR" title="${v.rotR}" aria-label="${v.rotR}">⟳</button>`
66	    + `<button type="button" data-c="high" aria-pressed="${W.view.high}">⇕ ${v.high}</button>`
67	    + `<button type="button" data-c="school" aria-pressed="${m === 'school'}">🏫 ${v.school}</button><button type="button" data-c="stage" aria-pressed="${m === 'stage'}">🎭 ${v.stage}</button>`
68	    + (rules().parking ? `<button type="button" data-c="park" aria-pressed="${m === 'park'}">🅿️</button>` : '')
69	    + `<button type="button" data-c="walls">🧱 ${v.walls} : ${t().wallModes[W.wallMode]}</button>`
70	    + `<button type="button" data-c="out" aria-label="−">−</button><button type="button" data-c="in" aria-label="+">+</button>`;
71	  for (const b of camBar.querySelectorAll('[data-c]')) b.onclick = () => camCmd(b.dataset.c);
72	  requestAnimationFrame(() => resize());
73	}
74	export function camCmd(c) {
75	  const v = W.view;
76	  if (c === 'rotL' || c === 'rotR') { v.rot = (v.rot + (c === 'rotL' ? 3 : 1)) % 4; if (['stage', 'podium', 'park'].includes(v.mode)) v.mode = G.pickedRoom ? 'room' : 'school'; W.cutTo(); }
77	  if (c === 'high') { v.high = !v.high; if (['stage', 'podium'].includes(v.mode)) v.mode = 'school'; W.cutTo(); }
78	  if (c === 'school') { G.pickedRoom = null; W.cutTo('school'); if (G.screen === 'prep') paintSheet(); }
79	  if (c === 'stage') { W.cutTo(v.mode === 'stage' ? 'school' : 'stage'); }
80	  if (c === 'park') { G.pickedRoom = null; W.cutTo(v.mode === 'park' ? 'school' : 'park'); }
81	  if (c === 'walls') W.setWallMode((W.wallMode + 1) % 3);
82	  if (c === 'in') W.zoomBy(1.25); if (c === 'out') W.zoomBy(0.8);
83	  if (G.run) G.run.auto = 'manual';
84	  paintCamBar();
85	}
86	export function pickRoom(r) { G.pickedRoom = r; W.cutTo(r ? 'room' : 'school'); if (G.screen === 'prep') paintSheet(); paintCamBar(); }
87	const TABS = () => ['order', 'formation', 'gouter', 'costumes', 'build', ...(rules().parking ? ['parking'] : []), 'shop', 'notebook'];
88	export function setTab(k) {
89	  G.tab = k; G.armed = null; W.setGhost(null);
90	  if (k !== 'build') { G.selected = null; W.showFurniture(); }
91	  if (k === 'formation') { G.pickedRoom = null; W.cutTo('stage'); }
92	  else if (k === 'costumes') { G.pickedRoom = null; W.cutTo('podium'); }
93	  else if (k === 'build') pickRoom('dr');
94	  else if (k === 'parking') { G.pickedRoom = null; W.cutTo('park'); }
95	  else if (['podium', 'park'].includes(W.view.mode)) W.cutTo('school');
96	  idle(); paintSheet(); paintCamBar();
97	}
98	export function showScreen(s) { G.screen = s; paintSheet(); hud(); }
99	export function paintSheet() {
100	  tabsEl.hidden = G.screen !== 'prep';
101	  const pop = document.getElementById('planpop'); if (pop) pop.hidden = true; // the formation tab shows it again when it is open
102	  if (G.screen === 'prep') {
103	    if (!TABS().includes(G.tab)) G.tab = 'order';
104	    tabsEl.innerHTML = TABS().map((k) => `<button type="button" role="tab" data-tab="${k}" aria-selected="${G.tab === k}">${esc(t().tabs[k])}</button>`).join('');
105	    for (const b of tabsEl.querySelectorAll('[data-tab]')) b.onclick = () => setTab(b.dataset.tab);
106	    ({ order: paintOrder, formation: paintFormation, gouter: paintGouter, costumes: paintCostumes, build: paintBuild, parking: paintParking, shop: paintShop, notebook: paintNotebook })[G.tab]();
107	    goEl.innerHTML = `<button type="button" class="reh" id="rehBtn">${esc(t().rehearse)}</button>` + (G.S.galaDone ? `<button type="button" class="gala" id="seasonBtn">${esc(t().newSeason)}</button><div class="hint wide" style="margin:0">${esc(t().galaDone)}</div>` : `<button type="button" class="gala" id="galaBtn">${esc(t().gala)}</button>`);
108	    goEl.querySelector('#rehBtn').onclick = () => beginRun('rehearsal');
109	    const gb = goEl.querySelector('#galaBtn'); if (gb) gb.onclick = () => beginRun('gala');
110	    const sb = goEl.querySelector('#seasonBtn'); if (sb) sb.onclick = nextSeason;
111	  } else if (G.screen === 'run') paintRunSheet(true);
112	  else if (G.screen === 'results') paintResults();
113	  requestAnimationFrame(() => resize());
114	}
115	
116	/* ---------------- the programme ---------------- */
117	let dragId = null;
118	function paintOrder() {
119	  const P = G.S.plan, s = G.S.season;
120	  sbody.innerHTML = `<h2>${esc(t().orderH)}</h2>${facts(t().orderFacts(s))}`
121	    + stepper('start', t().start, clockOf(P.start)) + stepper('interval', t().interval, durOf(P.interval))
122	    + `<p class="hint">${esc(t().orderHint)}</p><div class="cards" id="orderCards">${P.order.map((id, k) => {
123	      const kind = itemKind(id), locked = k === 0 || k === P.order.length - 1, dur = kind === 'interval' ? P.interval : kind === 'number' ? numDur(id) : null;
124	      const tags = kind === 'number' && s >= 3 ? `<span class="tags">${STYLES[NUMBERS[id].style].icon}${NUMBERS[id].mood === 'calme' ? '🐢' : '⚡'}</span>` : '';
125	      return `<div class="card${locked ? ' locked' : ''}${dragId === id ? ' dragging' : ''}" data-id="${id}">${dot(kind === 'number' ? NUMBERS[id].cls : null)}<span class="nm">${esc(itemName(id))}</span>${tags}<span class="du">${dur ? esc(durOf(dur)) : id === 'accueil' ? '4 min' : '3 min'}</span>${locked ? '<span class="du">🔒</span>' : `<span class="mv"><button type="button" data-mv="-1" aria-label="▲">▲</button><button type="button" data-mv="1" aria-label="▼">▼</button></span>`}</div>`;
126	    }).join('')}</div>`;
127	  bindSteppers((id, d) => { if (id === 'start') P.start = clamp(P.start + d * 300, RULES.startMin, RULES.startMax); if (id === 'interval') P.interval = clamp(P.interval + d * 300, RULES.intervalMin, RULES.intervalMax); W.drawClock(P.start); });
128	  for (const c of sbody.querySelectorAll('.card:not(.locked)')) {
129	    c.querySelectorAll('[data-mv]').forEach((b) => (b.onclick = (e) => { e.stopPropagation(); moveCard(c.dataset.id, +b.dataset.mv); }));
130	    c.addEventListener('pointerdown', (e) => { if (e.target.closest('button')) return; dragId = c.dataset.id; c.classList.add('dragging'); e.preventDefault(); });
131	  }
132	}
133	function moveCard(id, d) { const o = G.S.plan.order, i = o.indexOf(id), j = clamp(i + d, 1, o.length - 2); if (i === j) return; o.splice(i, 1); o.splice(j, 0, id); changed(); }
134	document.addEventListener('pointermove', (e) => {
135	  if (!dragId) return; const cards = [...sbody.querySelectorAll('#orderCards .card')], o = G.S.plan.order, i = o.indexOf(dragId);
136	  let j = i; for (let k = 1; k < cards.length - 1; k++) { const r = cards[k].getBoundingClientRect(); if (e.clientY > r.top && e.clientY < r.bottom) { j = k; break; } }
137	  if (j !== i) { o.splice(i, 1); o.splice(j, 0, dragId); paintOrder(); }
138	});
139	document.addEventListener('pointerup', () => { if (dragId) { dragId = null; changed(); } });
140	
141	/* ---------------- the formation and the choreography ---------------- */
142	let selMove = null, allMoves = false;
143	function numChips(onPick) {
144	  return `<div class="chips numchips">${activeNums().map((id) => `<button type="button" data-num="${id}" aria-pressed="${G.pickNum === id}">${dot(NUMBERS[id].cls)} ${esc(numName(id))}</button>`).join('')}</div>`;
145	}
146	function bindNumChips(after) { for (const b of sbody.querySelectorAll('[data-num]')) b.onclick = () => { G.pickNum = b.dataset.num; G.pickDancer = null; G.editB = false; selMove = null; idle(); after(); }; }
147	// the blocks of a dance get a colour each, in the order they were made
148	const BLOCK_COLORS = ['#86d9a6', '#b48cff', '#7cc6ff', '#ffb86b', '#ff9ec7', '#f5e36b', '#9fe0e0', '#d0b0ff'];
149	const MAX_BLOCKS = 8, MAX_CHAIN = 60;
150	let selBlock = {}, selChain = null;
151	const blockColor = (np, bid) => BLOCK_COLORS[Math.max(0, np.blocks.findIndex((b) => b.id === bid)) % BLOCK_COLORS.length];
152	const blockCounts = (b) => b.moves.reduce((s, mid) => s + MOVES[mid].c, 0);
153	// a chain's counts as a sum, equal blocks in a row grouped: "3 × 32 + 16"
154	export function chainSum(parts) {
155	  const out = []; for (const p of parts) { const last = out[out.length - 1]; if (last && last.v === p) last.n++; else out.push({ v: p, n: 1 }); }
156	  return out.map((x) => (x.n > 1 ? `${x.n} × ${x.v}` : `${x.v}`)).join(' + ') || '0';
157	}
158	function paintFormation() {
159	  if (!activeNums().includes(G.pickNum)) G.pickNum = activeNums().includes('G1') ? 'G1' : activeNums()[0];
160	  const id = G.pickNum, N = NUMBERS[id], cls = CLS[N.cls], np = G.S.plan.numbers[id], st = stageOf(G.S.school), dance = danceOf(np), info = routineInfo(dance.moves, N.style, false);
161	  if (info.swaps && !np.B) np.B = np.A.map((p) => ({ ...p }));
162	  if (!info.swaps) G.editB = false;
163	  if (!np.blocks.some((b) => b.id === selBlock[id])) selBlock[id] = np.blocks[0].id;
164	  const bid = selBlock[id], blk = np.blocks.find((b) => b.id === bid), binfo = routineInfo(blk.moves, N.style, false);
165	  if (selChain !== null && selChain >= np.chain.length) selChain = null;
166	  const res = forecast(), P = res.perf[id];
167	  let h = `<h2>${esc(t().formH)}</h2>${numChips()}`;
168	  h += facts([...t().musicFacts(durOf(numDur(id)), N.bpm), t().tuneFact(esc(nm(TUNES[id].title)), esc(nm(TUNES[id].by))), t().spanFact(clsName(N.cls), `${num(cls.span)} m`), t().hiddenFact, `${STYLES[N.style].icon} ${esc(styleName(N.style))}`]);
169	  const abChips = info.swaps ? `<button type="button" data-ab="A" aria-pressed="${!G.editB}">${esc(t().posA)}</button><button type="button" data-ab="B" aria-pressed="${G.editB}">${esc(t().posB)}</button>` : '';
170	  const planTools = `${abChips}<button type="button" data-ruler aria-pressed="${!!G.ruler}">${esc(t().ruler)}</button><button type="button" data-big>${esc(G.planBig ? t().smallPlan : t().bigPlan)}</button>`;
171	  const planSvg = stagePlanSvg(id, np, cls, st, info, blk.moves);
172	  h += `<p class="hint">${esc(t().formHint)}</p>`;
173	  h += G.planBig ? `<p class="hint">${esc(t().bigNote)}</p><div class="chips">${planTools}</div>` : planSvg + `<div class="chips">${planTools}</div>${G.ruler ? `<p class="hint">${esc(t().rulerHint)}</p>` : ''}`;
174	  h += `<p class="hint">${np.A.map((_, i) => `${i + 1} ${esc(dancerName(N.cls, i))}`).join(' · ')}</p>`;
175	  // the blocks, and the steps of the chosen one
176	  h += `<h3>${esc(t().blocksH)}</h3><p class="hint">${esc(t().blocksHint)}</p><div class="chips blocks">`;
177	  for (const b of np.blocks) h += `<button type="button" data-blk="${b.id}" aria-pressed="${b.id === bid}" style="border-left:7px solid ${blockColor(np, b.id)}">${esc(b.name)} <small>${esc(t().countsShort(blockCounts(b)))}</small></button>`;
178	  h += `</div><div class="chips"><button type="button" id="newBlk">${esc(t().newBlock)}</button><button type="button" id="copyBlk">${esc(t().copyBlock)}</button><button type="button" id="renBlk">${esc(t().renameBlock)}</button>${np.blocks.length > 1 ? `<button type="button" id="delBlk">${esc(t().delBlock)}</button>` : ''}</div>`;
179	  h += `<div class="seq blockseq" style="border-left-color:${blockColor(np, bid)}">`;
180	  blk.moves.forEach((mid, k) => {
181	    const m = MOVES[mid], l = binfo.links[k];
182	    h += `<button type="button" class="mvchip" data-k="${k}" aria-pressed="${selMove === k}"><span class="ic">${m.icon}</span><span class="mn">${esc(moveName(mid))}</span><span class="ct">${esc(t().countsShort(m.c))} · ${diffDots(m.d)}</span></button>`;
183	    if (l) h += `<span class="lk ${l.gap === 0 && !l.off ? 'ok' : l.gap === 2 ? 'bad' : 'meh'}" title="${l.off ? esc(t().offStyle) : ''}">${l.gap === 0 && !l.off ? '✨' : l.gap === 2 ? '💥' : '〰️'}</span>`;
184	  });
185	  if (!blk.moves.length) h += `<span class="hint">${esc(t().emptyBlock)}</span>`;
186	  h += `</div><p class="hint small">${esc(t().harmonyLegend)}</p>`;
187	  if (selMove !== null && blk.moves[selMove]) h += `<div class="chips"><button type="button" data-sm="-1">◀ ${esc(t().moveLeft)}</button><button type="button" data-sm="1">${esc(t().moveRight)} ▶</button><button type="button" data-sm="x">✕ ${esc(t().removeMove)}</button></div>`;
188	  h += `<p>${t().blockLen(esc(blk.name), blockCounts(blk))}</p>`;
189	  h += `<h3>${esc(t().addMoves)}</h3><div class="chips"><button type="button" id="filtBtn" aria-pressed="${!allMoves}">${esc(t().onlyStyle(styleName(N.style)))}</button><button type="button" id="allBtn" aria-pressed="${allMoves}">${esc(t().allMoves)}</button></div><div class="pal">`;
190	  for (const [mid, m] of Object.entries(MOVES)) {
191	    const suits = m.st === '*' || m.st.split(' ').includes(N.style); if (!allMoves && !suits) continue;
