321	function bindStagePlan(root, id, np, cls, st, info) {
322	  const svg = root.querySelector('#plan'), D = st.depth, Wd = st.halfW; let drag = null, moved = false, rDrag = null;
323	  const toPlan = (e) => { const pt = svg.createSVGPoint(); pt.x = e.clientX; pt.y = e.clientY; const q = pt.matrixTransform(svg.getScreenCTM().inverse()); return { x: q.x, z: D - q.y }; };
324	  const F = () => (G.editB && np.B ? np.B : np.A);
325	  for (const g of svg.querySelectorAll('[data-dot]')) g.addEventListener('pointerdown', (e) => { drag = +g.dataset.dot; moved = false; svg.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation(); });
326	  const ruler = svg.querySelector('#ruler');
327	  if (ruler) {
328	    ruler.querySelector('rect').addEventListener('pointerdown', (e) => { const q = toPlan(e); rDrag = { kind: 'move', dx: q.x - G.ruler.x, dz: q.z - G.ruler.z }; svg.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation(); });
329	    ruler.querySelector('#rulerTurn').addEventListener('pointerdown', (e) => { rDrag = { kind: 'turn' }; svg.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation(); });
330	  }
331	  svg.addEventListener('pointermove', (e) => {
332	    const q = toPlan(e);
333	    if (rDrag) {
334	      if (rDrag.kind === 'move') { G.ruler.x = q.x - rDrag.dx; G.ruler.z = q.z - rDrag.dz; }
335	      else G.ruler.a = Math.round(Math.atan2(q.z - G.ruler.z, q.x - G.ruler.x) * 180 / Math.PI / 5) * 5;
336	      ruler.setAttribute('transform', `translate(${G.ruler.x} ${D - G.ruler.z}) rotate(${-G.ruler.a})`); return;
337	    }
338	    if (drag === null) return; moved = true;
339	    const g = svg.querySelector(`[data-dot="${drag}"]`); g.querySelector('circle').setAttribute('cx', q.x); g.querySelector('circle').setAttribute('cy', D - q.z); g.querySelector('text').setAttribute('x', q.x); g.querySelector('text').setAttribute('y', D - q.z);
340	  });
341	  const drop = (e) => {
342	    if (rDrag) { rDrag = null; return; }
343	    if (drag === null) return; const i = drag; drag = null;
344	    if (moved) { const q = toPlan(e); F()[i] = { x: clamp(Math.round(q.x * 2) / 2, -Wd - 0.5, Wd + 0.5), z: clamp(Math.round(q.z * 2) / 2, 0, D) }; }
345	    G.pickDancer = i; changed();
346	  };
347	  svg.addEventListener('pointerup', drop); svg.addEventListener('pointercancel', () => { drag = null; rDrag = null; paintFormation(); });
348	}
