1	// The starting plan and the starting school, and how a season adds its new numbers. Pure: no DOM, no three.js.
2	import { hm, NUMBERS, CLS, LOGE, seasonRules, START } from './data.js';
3	
4	const xz = (pts) => pts.map(([x, z]) => ({ x, z }));
5	// each number's starting formation: every one fits on the stage except the seniors' "Lumière", a line a metre apart
6	// (the arms of a senior span 1.6 m: the first rehearsal shows their hands touching, as in round 1)
7	const FORMATIONS = {
8	  petits: xz([[-2.5, 1], [-0.5, 1], [1.5, 1], [-1.5, 2.5], [0.5, 2.5], [2.5, 2.5]]),
9	  moyens: xz([[-3.5, 1], [-1.5, 1], [0.5, 1], [2.5, 1], [-2.5, 2.5], [-0.5, 2.5], [1.5, 2.5], [3.5, 2.5], [-3, 4], [3, 4]]),
10	  grandes: xz([[-3, 1.5], [-1, 1.5], [1, 1.5], [3, 1.5], [-4, 3.5], [-2, 3.5], [2, 3.5], [4, 3.5]]),
11	  ados: xz([[-3, 1.5], [-1, 1.5], [1, 1.5], [3, 1.5], [-4, 3.5], [-2, 3.5], [2, 3.5], [4, 3.5]]),
12	  mamans: xz([[-3, 1.5], [0, 1.5], [3, 1.5], [-4.5, 3.5], [-1.5, 3.5], [1.5, 3.5]]),
13	};
14	const G1_LINE = xz([[-3.5, 1.5], [-2.5, 1.5], [-1.5, 1.5], [-0.5, 1.5], [0.5, 1.5], [1.5, 1.5], [2.5, 1.5], [3.5, 1.5]]);
15	// each number's starting phrase and how many times it repeats (one block, chained that many times). All fill their music
16	// exactly, except "Lumière": 16 × 32 = 512 counts for 480 counts of music, and a pirouette straight off the floor
17	const ROUTINES = {
18	  P1: { moves: ['plie', 'bras', 'saute', 'reception', 'tourne', 'plie', 'reverence'], repeats: 9 },
19	  P2: { moves: ['clap', 'chasseD', 'clap', 'chasseG', 'saute', 'reception'], repeats: 9 },
20	  M1: { moves: ['bras', 'descente', 'roulade', 'remonte', 'arabesque'], repeats: 12 },
21	  M2: { moves: ['kick', 'chasseD', 'kick', 'chasseG', 'sautChat', 'reception'], repeats: 12 },
22	  G1: { moves: ['plie', 'bras', 'arabesque', 'descente', 'pirouette', 'reverence'], repeats: 16 },
23	  G2: { moves: ['releve', 'pirouette', 'bras', 'chasseD', 'chasseG'], repeats: 15 },
24	  A1: { moves: ['toprock', 'vague', 'clap', 'moonwalk', 'chasseD'], repeats: 10 },
25	  A2: { moves: ['toprock', 'descente', 'freeze', 'remonte', 'vague', 'toprock'], repeats: 12 },
26	  F1: { moves: ['clap', 'chasseD', 'chasseG', 'tourne', 'kick', 'clap'], repeats: 8 },
27	};
28	const COSTUMES = {
29	  P1: { outfit: 'tutu', color: '#ff9ec7', shoes: 'demi', acc: 'noeud' }, P2: { outfit: 'jupette', color: '#ff6f91', shoes: 'demi', acc: 'aucun' },
30	  M1: { outfit: 'jupette', color: '#7cc6ff', shoes: 'pieds', acc: 'aucun' }, M2: { outfit: 'justaucorps', color: '#4f7cff', shoes: 'demi', acc: 'aucun' },
31	  G1: { outfit: 'justaucorps', color: '#b48cff', shoes: 'demi', acc: 'aucun' }, G2: { outfit: 'tutu', color: '#ffffff', shoes: 'demi', acc: 'aucun' },
32	  A1: { outfit: 'street', color: '#c23652', shoes: 'baskets', acc: 'aucun' }, A2: { outfit: 'street', color: '#2b2236', shoes: 'baskets', acc: 'aucun' },
33	  F1: { outfit: 'jupette', color: '#86d9a6', shoes: 'demi', acc: 'noeud' },
34	};
35	export const DEFAULT_HAIR = { petits: 'chignon', moyens: 'queue', grandes: 'chignon', ados: 'queue', mamans: 'carre' };
36	
37	export function numberPlan(id) {
38	  const cls = NUMBERS[id].cls, A = (id === 'G1' ? G1_LINE : FORMATIONS[cls]).map((p) => ({ ...p }));
39	  return { A, B: null, ...oneBlock(ROUTINES[id].moves, ROUTINES[id].repeats), costume: { ...COSTUMES[id] } };
40	}
41	// a dance as blocks and a chain: round 2's "phrase × repeats" is one block, chained `repeats` times
42	export const oneBlock = (moves, repeats) => ({ blocks: [{ id: 'a', name: 'A', moves: [...moves] }], chain: Array(repeats).fill('a') });
43	// an older save's number (moves + repeats) becomes one block, chained as many times: the same dance, nothing lost
44	export function migrateNumber(np) {
45	  if (np.blocks) return np;
46	  const { moves = [], repeats = 1, ...rest } = np;
47	  return { ...rest, ...oneBlock(moves, repeats) };
48	}
49	
50	export function defaultPlan() {
51	  const numbers = {};
52	  for (const id of ['P1', 'P2', 'M1', 'M2', 'G1', 'G2']) numbers[id] = numberPlan(id);
53	  return {
54	    start: hm(20, 0), interval: 1500,
55	    order: ['accueil', 'P1', 'M1', 'G1', 'entracte', 'P2', 'M2', 'G2', 'final'],
56	    numbers, hair: { petits: 'chignon', moyens: 'queue', grandes: 'chignon' },
57	    snack: 'rien', cakeG: 1500, bottles: 3, crepes: 0, compotes: 0,
58	    parking: { width: 2.5, doors: 30 }, backdrop: 'nuit',
59	  };
60	}
61	
62	export function defaultSchool() {
63	  return {
64	    name: '', logeCols: LOGE.cols, stars: START.stars, earned: 0, owned: {}, upgrades: {},
65	    furniture: [
66	      { id: 'banc', c: 1, r: 4, rot: 0 }, { id: 'portant', c: 6, r: 5, rot: 0 },
67	      { id: 'miroir', c: 3, r: 0, rot: 0 }, { id: 'miroir', c: 5, r: 0, rot: 0 },
68	    ],
69	  };
70	}
71	
72	// a new season brings its new classes: their numbers join the programme just before the interval and the finale
73	const ARRIVALS = { ados: [['A1', 'entracte'], ['A2', 'final']], mamans: [['F1', 'final']] };
74	export function addSeasonNumbers(plan, season) {
75	  for (const cls of seasonRules(season).classes) {
76	    if (!ARRIVALS[cls]) continue;
