581	    case 'yawn': return S.yawn(numName(a[0]));
582	    case 'late': return S.late(durOf(a[0]));
583	    case 'onTime': return S.onTime(clockOf(a[0]));
584	    case 'collide': return S.collide(dancerName(a[0], a[1]), dancerName(a[0], a[2]));
