591	    case 'ankle': return S.ankle(dancerName(a[0], a[1]), moveName(a[2]));
592	    case 'musicLong': return S.musicLong(numName(a[0]), a[1]);
593	    case 'musicShort': return S.musicShort(numName(a[0]), durOf(a[1]));
594	    case 'applause': return S.applause(numName(a[0]), a[1]);
595	    case 'cakeOut': return S.cakeOut(clsName(a[0]));
596	    case 'juiceOut': return S.juiceOut(clsName(a[0]));
597	    default: return S[k] ? S[k](...a) : k;
598	  }
599	}
600	const L = (a, b = '', cls = '') => `<div class="${cls}"><span>${a}</span>${b !== '' ? `<span>${b}</span>` : ''}</div>`;
601	const card = (title, ok, sayList, sum, badge = '') => `<div class="verdict${ok ? '' : ' fix'}"><div class="vt">${ok ? '🌟' : '🔧'} ${esc(title)} · ${esc(ok ? t().perfect : t().fix)}${badge ? ` <span class="badge">${badge}</span>` : ''}</div>${sayList.map((s) => `<p>${esc(s)}</p>`).join('')}${sum ? `<details><summary>${esc(t().why)}</summary><div class="sum">${sum}</div></details>` : ''}</div>`;
602	export function verdictCards(R) {
603	  const S = t().sum, P = R.plan, O = R.order, G2 = R.gouter, SY = t().say;
604	  let out = '';
605	  // the programme
606	  let os = L(esc(S.start), esc(clockOf(P.start)));
607	  os += L(esc(S.hair(O.hairTotal, R.loge.postes, O.hairMin)));
608	  if (O.startLate) os += L(esc(S.realStart), esc(clockOf(O.start)), 'tot');
609	  for (const it of O.items) {
610	    if (it.co) os += L(`+ ${esc(durOf(it.co))} · ${esc(S.setChange)}`);
611	    if (it.fl) os += L(`+ ${esc(durOf(it.fl))} · ${esc(S.floor(it.floor))}`);
612	    if (it.change) { os += L(`<i>${esc(S.change(clsName(NUMBERS[it.id].cls), it.change.min))} ${it.change.lines.map(([k, m, o]) => esc(k === 'outfit' ? S.chLines.outfit(nm(OUTFITS[o]), m) : S.chLines[k](m))).join(' · ')}</i>`); }
613	    if (it.wait) os += L(`+ ${esc(durOf(it.wait))} · ${esc(S.waitCos)}`);
614	    os += L(`+ ${esc(durOf(it.dur))} · ${esc(itemName(it.id))}`, esc(clockOf(it.end)));
615	  }
616	  os += L(`${esc(S.end)} : ${esc(clockOf(O.end))} ${O.end <= RULES.hallCloses ? '≤' : '>'} ${esc(clockOf(RULES.hallCloses))}`, '', 'tot');
617	  if (O.lastEnd.petits !== undefined) os += L(`${esc(S.petitsEnd)} ${esc(clockOf(O.lastEnd.petits))} ${O.lastEnd.petits <= RULES.bedtime ? '≤' : '>'} ${esc(clockOf(RULES.bedtime))}`, '', 'tot');
