1	// The dancers: the castle's box people, dressed for each number. A costume is { outfit, color, shoes, acc }, the hair is the
2	// class's. Every look is built from boxes and cylinders so that a new costume is one more `if` here and one row in data.js.
3	import * as T from 'three';
4	import { std, box, cyl, M } from './world.js';
5	import { CLASSES, SHOES } from './data.js';
6	import { rngFor } from './engine.js';
7	
8	export const P_SCALE = 0.47;   // the castle's people are 3.4 units tall: a senior is 1.6 m
9	const SKINS = ['#f1c9a5', '#e8b48f', '#d9a076', '#b07a4b', '#7a4b2b', '#4a2e1b'], HAIRC = ['#2b1b10', '#7a4a1f', '#e3b04b', '#c4392f', '#3b2416', '#d8c08a'];
10	export function lookOf(cls, i) { const r = rngFor(CLASSES.findIndex((c) => c.id === cls) * 101 + i * 7 + 3); return { skin: SKINS[Math.floor(r() * SKINS.length)], hair: HAIRC[Math.floor(r() * HAIRC.length)], face: r() < 0.25 ? 'freckles' : r() < 0.4 ? 'blush' : 'none' }; }
11	export const lighter = (hex, k = 0.35) => new T.Color(hex).lerp(new T.Color(0xffffff), k);
12	const darker = (hex, k = 0.35) => new T.Color(hex).lerp(new T.Color(0x000000), k);
13	const limb = (w, h, d, mat, x, y, z) => { const p = new T.Group(); p.position.set(x, y, z); p.add(box(w, h, d, mat, 0, -h / 2, 0)); return p; };
14	const ball = (r, mat, x, y, z, detail = 0) => { const m = new T.Mesh(new T.IcosahedronGeometry(r, detail), mat); m.position.set(x, y, z); m.castShadow = true; return m; };
15	const glassy = (c, o = 0.55) => new T.MeshStandardMaterial({ color: c, transparent: true, opacity: o, roughness: 0.3, flatShading: true, side: T.DoubleSide });
16	
17	function wings(body, mat, big) {
18	  for (const s of [-1, 1]) {
19	    const w = new T.Group(); w.position.set(s * 0.2, 2.0, -0.3); w.rotation.y = s * 0.5;
20	    w.add(box(big ? 1.0 : 0.7, big ? 1.1 : 0.8, 0.03, mat, s * (big ? 0.5 : 0.35), 0.2, 0));
21	    w.add(box(big ? 0.7 : 0.5, 0.55, 0.03, mat, s * (big ? 0.4 : 0.3), -0.45, 0));
22	    body.add(w);
23	  }
24	}
25	export function makeDancer(look, cos, hairId, scale) {
26	  const g = new T.Group(), body = new T.Group(); g.add(body);
27	  const c = cos.color, skin = std(look.skin), hair = std(look.hair), suit = std(c), tights = std(0xf6d3c6);
28	  const shoeDef = SHOES[cos.shoes] || SHOES.demi, shoes = std(shoeDef.color || look.skin);
29	  // the head and the face
30	  body.add(box(0.9, 0.9, 0.9, skin, 0, 2.55, 0));
31	  for (const ex of [-0.2, 0.2]) { body.add(box(0.22, 0.17, 0.04, M.white, ex, 2.6, 0.455)); body.add(box(0.11, 0.15, 0.05, M.black, ex + (ex < 0 ? 0.04 : -0.04), 2.6, 0.47)); }
32	  body.add(box(0.24, 0.05, 0.04, std(0xc0405a), 0, 2.3, 0.46));
33	  if (look.face === 'freckles') for (const [x, y] of [[-0.3, 2.45], [-0.22, 2.4], [0.22, 2.4], [0.3, 2.45]]) body.add(box(0.05, 0.05, 0.03, std(0xb5683c), x, y, 0.46));
34	  if (look.face === 'blush') for (const s of [-1, 1]) body.add(box(0.17, 0.08, 0.03, std(0xff8fa3), s * 0.3, 2.42, 0.46));
35	  // the hair
