import { G, save, resetAll } from './state.js';
import {
  RULES, CLS, NUMBERS, numDur, itemKind, STYLES, MOVES, MAX_MOVES, LEVELS, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE, SNACKS, UPGRADES,
  BACKDROPS, PARKING, COLORS, seasonRules, hm,
