export function rotateArmed() { if (!G.armed) return; G.armed.rot = (G.armed.rot + 1) % 4; if (W.ghost.f) { const f = { ...W.ghost.f, rot: G.armed.rot }; showGhost(f); } }
export function rotateSelected() {
