  f.rot = (f.rot + 1) % 4;
  if (!fits(f, G.S.school.furniture, cols, f)) { const fp = footprint(f); f.c = clamp(f.c, 0, cols - fp.w); f.r = clamp(f.r, 0, LOGE.rows - fp.d); if (!fits(f, G.S.school.furniture, cols, f)) Object.assign(f, old); }
