  gs += L(esc(S.total(G2.needKcal)), '', 'tot');
  const parts = [`${P.cakeG} g × 4 = ${G2.offer.cake} kcal`, ...(P.crepes ? [`${P.crepes} × 150 = ${G2.offer.crepes}`] : []), ...(P.compotes ? [`${P.compotes} × 70 = ${G2.offer.compotes}`] : [])].join(' + ');
