      h += `<div class="step${now ? ' now' : past ? ' done' : ''}${bad ? ' bad' : ''}" data-k="${k}"><span class="ic">${m.icon}</span><span class="mn">${esc(moveName(d.moves[k]))}</span><span class="out">${out}</span></div>`;
