  s += `<rect x="${-Wd - 0.9}" y="-0.5" width="0.9" height="${D + 0.5}" fill="#1b1720"/><rect x="${Wd}" y="-0.5" width="0.9" height="${D + 0.5}" fill="#1b1720"/>`;
