      return `<button type="button" data-piece="${id}" aria-pressed="${G.armed && G.armed.id === id}" class="${own ? '' : 'locked'}"><span>${p.icon}</span>${esc(nm(p))}<small>${esc(own ? tags : `${t().buy(p.price)} · ${tags}`)}</small></button>`;
    }).join('')}</div>`;
