    if (drag === null) return; const i = drag; drag = null;
    if (moved) { const q = toPlan(e); F()[i] = { x: clamp(Math.round(q.x * 2) / 2, -Wd - 0.5, Wd + 0.5), z: clamp(Math.round(q.z * 2) / 2, 0, D) }; }
