  if (O.lastEnd.petits !== undefined) os += L(`${esc(S.petitsEnd)} ${esc(clockOf(O.lastEnd.petits))} ${O.lastEnd.petits <= RULES.bedtime ? '≤' : '>'} ${esc(clockOf(RULES.bedtime))}`, '', 'tot');
