  h += '<div class="steps">';
  for (const mk of d.marks) {
    if (mk.k1 === mk.k0) continue;
    h += `<div class="blk" style="border-left-color:${blockColor(np, mk.block)}"><div class="bh">${esc(byId[mk.block].name)} <small>${mk.j + 1}</small></div>`;
