    sbody.innerHTML = `<h2>${esc(t().live(run.mode))}</h2>${trySteps(run, false)}<div class="feed">${run.feed.slice().reverse().map((f) => `<div><b>${esc(clockOf(f.t, false))}</b> ${esc(f.text)}</div>`).join('')}</div>`;
    const now = sbody.querySelector('.step.now');
