} from './ui.js';
import { applySettings } from './settings.js';
import { GS, loadSettings, bindGear, openGate, openSettings, closeSettings, sayApplied } from './grownups.js';
import { getFile, flush } from './store.js';
import { clean, isRude } from './words.js';

// the grown-ups' settings are laid over the default rows first, then the save is opened against those rows
const [settingsFile, saved] = await Promise.all([loadSettings(), getFile('save')]);
applySettings(settingsFile);
load(saved.reached ? saved.data : null);
onSay(sayText, toast);
buildDancers(); refreshWorld(); idle(); idleScene(); paintCamBar(); showScreen('prep'); resize();
document.fonts?.ready.then(() => W.drawSign(clean(G.S.school.name, t().school, 40)));
showIntro();

$lang();
function $lang() {
  document.getElementById('langBtn').onclick = () => { G.lang = G.lang === 'fr' ? 'en' : 'fr'; save(); paintCamBar(); paintSheet(); hud(); document.getElementById('soundBtn').title = t().sound(soundOn()); W.drawSign(clean(G.S.school.name, t().school, 40)); };
  document.getElementById('introBtn').onclick = () => showIntro(true);
  const sb = document.getElementById('soundBtn'), paintSound = () => { sb.textContent = soundOn() ? '🔊' : '🔇'; sb.title = t().sound(soundOn()); sb.setAttribute('aria-label', sb.title); };
  sb.onclick = () => { setSound(!soundOn()); save(); paintSound(); };
  paintSound();
  const gear = document.getElementById('gearBtn'); gear.title = t().gs.gear; gear.setAttribute('aria-label', t().gs.gear);
  bindGear(gear);
}
sayApplied();

/* ---------------- the pointer on the 3D view ---------------- */
const canvas = W.canvas, ptrs = new Map(); let pinch0 = 0, zoom0 = 1;
canvas.addEventListener('contextmenu', (e) => { e.preventDefault(); if (G.armed) rotateArmed(); });
canvas.addEventListener('pointerdown', (e) => { ptrs.set(e.pointerId, { x: e.clientX, y: e.clientY, x0: e.clientX, y0: e.clientY, t0: performance.now(), button: e.button, type: e.pointerType }); canvas.setPointerCapture(e.pointerId); if (ptrs.size === 2) { const [a, b] = [...ptrs.values()]; pinch0 = Math.hypot(a.x - b.x, a.y - b.y); zoom0 = W.view.zoom; } });
