  sbody.querySelector('#resetBtn').onclick = () => { if (confirm(t().resetAsk)) { resetAll(); G.pickNum = 'G1'; buildDancers(); refreshWorld(); idle(); paintCamBar(); showScreen('prep'); showIntro(); } };
}

/* ---------------- the run ---------------- */
export function beginRun(mode, tryId) {
