  goEl.innerHTML = `<button type="button" class="reh wide" id="backBtn">${esc(t().back)}</button>` + (run.mode === 'gala' ? `<button type="button" class="gala wide" id="nextBtn">${esc(t().newSeason)}</button>` : '');
