    G.S.notebook.unshift({ season: G.S.season, at: new Date().toISOString().slice(0, 10), points: R.points, satisfaction: R.parents.satisfaction, nums: Object.fromEntries(Object.values(R.perf).map((p) => [p.id, p.total])) });
