  goEl.innerHTML = `<button type="button" class="reh" id="spdBtn">⏩ ${esc(t().speed)} ×${G.speed}</button>`
    + (run.mode !== 'try' ? `<button type="button" class="reh" id="folBtn" aria-pressed="${G.follow}">${esc(t().follow)} ${G.follow ? '✓' : ''}</button>` : '')
